// Headless integration tests against a real libmpv (vo=null, ao=null).
//
// Requires libmpv: set MPV_KIT_LIBMPV_PATH or have it on the loader path.
// Media is generated by mpv itself via lavfi, so no fixture files are needed.
@TestOn('vm')
library;

import 'dart:async';
import 'dart:ffi';
import 'dart:typed_data';

import 'package:ffi/ffi.dart';
import 'package:mpv_kit/mpv_kit.dart';
import 'package:test/test.dart';

/// 2 秒彩条 + 正弦音的 lavfi 合成源。
const _lavfi = 'av://lavfi:testsrc2=size=320x240:rate=30:duration=2';

Mpv _create() => Mpv.create(options: const {
      'vo': 'null',
      'ao': 'null',
      'idle': 'yes',
      'terminal': 'no',
    });

Future<T> _firstWhere<T extends MpvEventData>(Mpv mpv,
        [bool Function(T)? test]) =>
    mpv.events
        .where((e) => e is T && (test == null || test(e)))
        .cast<T>()
        .first
        .timeout(const Duration(seconds: 10));

void main() {
  group('library', () {
    test('loads and exposes client API 2.x', () {
      final b = MpvLibrary.open();
      final (major, _) = MpvLibrary.apiVersion(b);
      expect(major, 2);
    });

    test('every bound symbol resolves', () {
      final b = MpvLibrary.open();
      for (final s in MpvBindings.symbols) {
        expect(b.library.providesSymbol(s), isTrue, reason: s);
      }
      expect(MpvBindings.symbols, hasLength(54));
    });
  });

  group('node conversion', () {
    test('round-trips every value kind', () {
      final value = <String, Object?>{
        's': 'héllo 世界',
        'b': true,
        'i': -1 << 40,
        'd': 3.25,
        'n': null,
        'bytes': Uint8List.fromList([0, 1, 255]),
        'list': [1, 'two', <Object?>[], <String, Object?>{}],
      };
      final back = using((a) => readNode(writeNode(value, a)));
      expect(back, equals(value));
    });

    test('rejects unsupported types', () {
      expect(() => using((a) => writeNode(DateTime(2000), a)),
          throwsArgumentError);
    });
  });

  group('Mpv', () {
    late Mpv mpv;
    setUp(() => mpv = _create());
    tearDown(() => mpv.dispose());

    test('secure defaults are applied', () {
      expect(mpv.getProperty('load-scripts'), isFalse);
      expect(mpv.getProperty('config'), isFalse);
      // ytdl only exists in Lua-enabled builds; absent means disabled.
      expect(mpv.tryGetProperty('ytdl'), anyOf(isNull, isFalse));
    });

    test('typed property get/set round-trip', () {
      mpv.setProperty('volume', 42.5);
      expect(mpv.getProperty('volume'), 42.5);
      mpv.setProperty('mute', true);
      expect(mpv.getProperty('mute'), isTrue);
      mpv.setPropertyString('speed', '1.5');
      expect(mpv.getPropertyString('speed'), startsWith('1.5'));
      expect(mpv.getPropertyString('volume', osd: true), isNotNull);
    });

    test('errors map to MpvException with typed code', () {
      expect(
          () => mpv.getProperty('no-such-property'),
          throwsA(isA<MpvException>().having(
              (e) => e.error, 'error', MpvError.propertyNotFound)));
      expect(mpv.tryGetProperty('duration'), isNull);
    });

    test('command returns structured result', () {
      final r = mpv.command(['expand-text', r'${volume}']);
      expect(r, isA<String>());
    });

    test('async property round-trip', () async {
      await mpv.setPropertyAsync('volume', 10);
      expect(await mpv.getPropertyAsync('volume'), 10.0);
      await expectLater(mpv.getPropertyAsync('nope'),
          throwsA(isA<MpvException>()));
    });

    test('plays synthetic media and emits lifecycle events', () async {
      final loaded = _firstWhere<FileLoadedEvent>(mpv);
      final ended = _firstWhere<EndFileEvent>(mpv);
      mpv.command(['loadfile', _lavfi]);
      await loaded;
      expect(mpv.getProperty('width'), 320);
      // lavfi is a stream: duration may be unavailable or approximate.
      expect(mpv.tryGetProperty('duration'), anyOf(isNull, isA<double>()));
      final end = await ended;
      expect(end.reason, EndFileReason.eof);
    });

    test('observeProperty streams changes and unobserves on cancel', () async {
      final values = <Object?>[];
      final sub = mpv.observeProperty('volume').listen(values.add);
      await Future<void>.delayed(const Duration(milliseconds: 100));
      mpv.setProperty('volume', 77);
      await Future<void>.delayed(const Duration(milliseconds: 200));
      await sub.cancel();
      expect(values, contains(77.0));
    });

    test('async command completes via COMMAND_REPLY', () async {
      final cmd = mpv.commandAsync(['expand-text', 'abc']);
      expect(await cmd.result, 'abc');
    });

    test('log messages are delivered', () async {
      mpv.requestLogMessages('v');
      final log = _firstWhere<LogMessageEvent>(mpv);
      mpv.command(['loadfile', _lavfi]);
      expect((await log).text, isNotEmpty);
    });

    test('hooks pause loading until continued', () async {
      mpv.hookAdd('on_load');
      final hook = _firstWhere<HookEvent>(mpv);
      final loaded = _firstWhere<FileLoadedEvent>(mpv);
      mpv.command(['loadfile', _lavfi]);
      final h = await hook;
      expect(h.name, 'on_load');
      mpv.hookContinue(h.id);
      await loaded;
    });

    test('sub-client shares the core', () {
      final client = mpv.createClient('child');
      try {
        mpv.setProperty('volume', 33);
        expect(client.getProperty('volume'), 33.0);
        expect(client.clientName, 'child');
      } finally {
        client.dispose();
      }
    });

    test('dispose is idempotent and fails pending requests', () async {
      final pending = mpv.getPropertyAsync('volume');
      mpv.dispose();
      mpv.dispose();
      expect(mpv.isDisposed, isTrue);
      // 可能已在 dispose 前收到应答，二者均合法
      await pending.then((_) {}, onError: (Object e) {
        expect(e, isA<StateError>());
      });
    });
  });

  test('raw bindings remain usable for unwrapped calls', () {
    final mpv = _create();
    addTearDown(mpv.dispose);
    expect(mpv.bindings.getTimeUs(mpv.handle), greaterThan(0));
    expect(mpv.handle, isNot(nullptr));
  });
}
